    "productDetails": "{\n  \"form\": \"Профессиональная система химического пилинга\",\n  \"size\": \"2мл x 10шт\",\n  \"target\": \"Обновление кожи и отшелушивание\",\n  \"technology\": \"Комплекс Multi-AHA с природными кислотами\",\n  \"keyBenefits\": \"Удаление омертвевших клеток, обновление клеток, осветление кожи, выравнивание тона\",\n  \"usage\": \"Только профессиональные процедуры\",\n  \"skinType\": \"Всех типов кожи, особенно тусклой и текстурированной\",\n  \"application\": \"Нанесите равномерно на лицо лицензированным специалистом\",\n  \"testing\": \"Дерматологически протестировано\",\n  \"origin\": \"Южная Корея\"\n}",
    "keyFeatures": "[\n  {\n    \"title\": \"Комплекс природных AHA-кислот\",\n    \"description\": \"Мультикислотная формула с гликолевой, молочной, миндальной и фитиновой кислотами, полученными из природных источников, для мягкого, но эффективного отшелушивания.\"\n  },\n  {\n    \"title\": \"Улучшение обновления клеток\",\n    \"description\": \"Способствует естественному обновлению кожи, удаляя омертвевшие поверхностные клетки и способствуя росту новых здоровых клеток.\"\n  },\n  {\n    \"title\": \"Профессиональная формула\",\n    \"description\": \"Специально разработана для профессионального использования для обеспечения контролируемых и эффективных результатов пилинга.\"\n  },\n  {\n    \"title\": \"Пептидная поддержка\",\n    \"description\": \"Усилена sh-Polypeptide-7 для регенерации кожи и поддержки заживления во время процесса обновления.\"\n  }\n]",
