    "ingredients": "[\n  {\n    \"name\": \"CUREBIOME (Пробиотики и пребиотики)\",\n    \"description\": \"Продвинутая технология микробиома, которая корректирует баланс микробиома кожи и способствует здоровой флоре кожи.\"\n  },\n  {\n    \"name\": \"FENSEBIOME™ (Ацетил гептапептид-4)\",\n    \"description\": \"Инновационный пептид, который усиливает естественные защитные механизмы кожи и здоровье микробиома.\"\n  },\n  {\n    \"name\": \"Hyaluronan 10 Multi-Complex\",\n    \"description\": \"Многомолекулярный комплекс гиалуроновой кислоты, который обеспечивает глубокую гидратацию и наполняющие эффекты.\"\n  },\n  {\n    \"name\": \"Масло ши (Butyrospermum Parkii)\",\n    \"description\": \"Натуральный смягчающий агент, который обеспечивает дополнительное увлажнение и помогает поддерживать естественный барьер кожи.\"\n  }\n]",
    "howToUse": "[\n  {\n    \"step\": \"Подготовка\",\n    \"instruction\": \"Тщательно очистите кожу перед применением\"\n  },\n  {\n    \"step\": \"Применение\",\n    \"instruction\": \"Держите флакон на расстоянии 15-20 см от лица и равномерно распыляйте\"\n  },\n  {\n    \"step\": \"Впитывание\",\n    \"instruction\": \"Аккуратно похлопайте спрей по коже кончиками пальцев\"\n  },\n  {\n    \"step\": \"Частота использования\",\n    \"instruction\": \"Используйте утром и вечером или по мере необходимости в течение дня\"\n  },\n  {\n    \"step\": \"Многослойность\",\n    \"instruction\": \"Можно использовать до или после других средств по уходу за кожей\"\n  }\n]",
