    "productDetails": "{\n  \"form\": \"Увлажняющая сыворотка на основе кокосовой воды\",\n  \"size\": \"30мл\",\n  \"target\": \"Глубокая гидратация и восстановление увлажнения\",\n  \"technology\": \"4-ступенчатая система гидратации с многомолекулярной гиалуроновой кислотой\",\n  \"keyBenefits\": \"Глубокая гидратация, удержание влаги, противовоспалительная защита\",\n  \"usage\": \"Ежедневное применение утром и вечером\",\n  \"skinType\": \"Всех типов кожи, особенно сухой и обезвоженной\",\n  \"origin\": \"Южная Корея\"\n}",
